<?php get_header(); ?>
<section class="article-page"><div class="container article-container"><?php while (have_posts()) : the_post(); ?><header class="article-header"><div class="card-meta"><?php echo wp_kses_post(bcm_category_badge()); ?><span><?php echo esc_html(get_the_date('d/m/Y')); ?></span><span><?php echo esc_html(bcm_post_reading_time()); ?> phút đọc</span></div><h1><?php the_title(); ?></h1><?php if (has_excerpt()) : ?><p class="article-lead"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><div class="article-byline"><span class="byline-avatar"><?php echo esc_html(mb_substr(get_the_author(), 0, 1)); ?></span><span><strong><?php the_author(); ?></strong><small>Người viết · Blog CMS Magazine</small></span></div></header><?php if (has_post_thumbnail()) : ?><div class="article-featured-image"><?php the_post_thumbnail('full'); ?></div><?php endif; ?><div class="entry-content"><?php the_content(); wp_link_pages(); ?></div><div class="article-taxonomy"><?php the_tags('<span>Thẻ:</span> ', ' ', ''); ?></div><?php if (comments_open() || get_comments_number()) { comments_template(); } ?><nav class="post-navigation" aria-label="Bài viết trước và tiếp theo"><div><?php previous_post_link('%link', '← Bài viết trước'); ?></div><div><?php next_post_link('%link', 'Bài viết tiếp theo →'); ?></div></nav><?php endwhile; ?></div></section>
<?php get_footer(); ?>
